// NBA and WNBA player names, sourced from the nba_api package
// (https://github.com/swar/nba_api), which bundles official NBA.com/WNBA.com
// static player data. MIT licensed.
// 6204 unique player names (NBA + WNBA combined), first-name + last-name only.
// Each entry also includes lastYear (their final/most recent season), used
// for the "guess an older player" scoring bonus. NBA year data comes from a
// separate community-maintained index; WNBA players (and a small number of
// very recent/unmatched NBA players) default to the current year, since the
// WNBA only began in 1997 -- meaning at most a handful of its earliest
// players could ever qualify for even the smallest bonus tier anyway.
//
// Entries with an initials field are names where the game's default (first word +
// last word of fullName) would give the wrong initials: a multi-word last name
// (e.g. "George H. Bon Salle" -> "GB") or a generational suffix (e.g. "Jaren Jackson
// Jr." -> "JJ"). The initials are the first letter of the first word and the first
// letter of the whole last name, from nba_api's separate last_name field (used only
// where it is a proper trailing part of the name). The game uses this field when present.
// "Nikola Đurišić" also carries initials ("ND"): the game cannot reduce "Đ" to a plain letter on its own.
//
// Compiled for use in "Daily Duograms" — Copyright © 2026 UVM87 Games.
// Note: the underlying player names are public factual data and are not,
// by themselves, copyrightable -- this notice covers the game code that
// uses this data, not the raw names.
//
// Works in both the browser (just declares a global "athletes" array)
// and in Node (also exports it via module.exports), so the same file
// works whether it is loaded with a <script> tag or require()'d.

